export class AfterIteration {
 summarize(chunks: string[]): string {
  let merged = ''
  for (const chunk of chunks) {
   console.log(chunk)
  }
  merged = 'finished'
  return merged
 }
}

export class ChunkAssembler {
 assemble(chunks: string[]): string {
  let merged = ''
  for (const chunk of chunks) {
   merged = merged + chunk
  }
  return merged
 }
}

export class AfterIteration {
 summarize(chunks: string[]): string {
  let merged = ''
  for (const chunk of chunks) {
   console.log(chunk)
  }
  merged = 'finished'
  return merged
 }
}

export class DeferredAssembly {
 schedule(chunks: string[]): string {
  let merged = ''
  for (const chunk of chunks) {
   queueMicrotask(() => { merged = chunk })
  }
  return merged
 }
}
